\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-0.5, xmax=3.9, ymin=-0.08, ymax=0.7, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2,3}, ytick={0.2,0.4}]
